(lib.Консоль = function(mode,startPosition,loop,reversed) {
if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		// Анимация для g1
		var g1 = this.g1;
		var centerX_g1 = g1.x;
		var centerY_g1 = g1.y;
		var centerRotation_g1 = g1.rotation;
		var amplitude_g1 = 3;
		var amplitudeRotation_g1 = 6;
		var speedX_g1 = 0.02;
		var speedY_g1 = 0.03;
		var speedRotation_g1 = 0.02;
		var counterX_g1 = 0;
		var counterY_g1 = 0;
		var counterRotation_g1 = 0;
		
		function updateG1() {
		    counterX_g1 += speedX_g1;
		    counterY_g1 += speedY_g1;
		    counterRotation_g1 += speedRotation_g1;
		    
		    g1.x = centerX_g1 + Math.sin(counterX_g1) * amplitude_g1;
		    g1.y = centerY_g1 + Math.sin(counterY_g1) * amplitude_g1;
		    g1.rotation = centerRotation_g1 + Math.sin(counterRotation_g1) * amplitudeRotation_g1;
		}
		
		this.addEventListener("tick", updateG1);
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// g1
	this.g1 = new lib.Консол();
	this.g1.name = "g1";

	this.timeline.addTween(cjs.Tween.get(this.g1).wait(1));

	this._renderFirstFrame();

}).prototype = getMCSymbolPrototype(lib.Консоль, new cjs.Rectangle(-143,-95,286,190.2), null);


