(lib.helic_1 = function(mode,startPosition,loop,reversed) {
if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		// Анимация для g2
		var g2 = this.g2;
		var centerX_g2 = g2.x;
		var centerY_g2 = g2.y;
		var centerRotation_g2 = g2.rotation;
		
		var amplitudeX_g2 = 3;
		var amplitudeY_g2 = 8;
		var amplitudeRotation_g2 = 2;
		
		// Слегка меняем скорость для g2, чтобы они не двигались в одном ритме
		var speedX_g2 = 0.025; 
		var speedY_g2 = 0.015;
		var speedRotation_g2 = 0.03;
		
		// Сдвигаем начальную фазу случайным образом
		var counterX_g2 = Math.random() * 100;
		var counterY_g2 = Math.random() * 100;
		var counterRotation_g2 = Math.random() * 100;
		
		function updateG2() {
		    counterX_g2 += speedX_g2;
		    counterY_g2 += speedY_g2;
		    counterRotation_g2 += speedRotation_g2;
		    
		    g2.x = centerX_g2 + Math.sin(counterX_g2) * amplitudeX_g2;
		    g2.y = centerY_g2 + Math.sin(counterY_g2) * amplitudeY_g2;
		    g2.rotation = centerRotation_g2 + Math.sin(counterRotation_g2) * amplitudeRotation_g2;
		}
		
		this.addEventListener("tick", updateG2);
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// g2
	this.g2 = new lib.heli();
	this.g2.name = "g2";

	this.timeline.addTween(cjs.Tween.get(this.g2).wait(1));

	this._renderFirstFrame();

}).prototype = getMCSymbolPrototype(lib.helic_1, new cjs.Rectangle(-147.1,-58,249.3,168.4), null);


